from vector_scaling import build_card

OUT=ROOT/'geometry-course/textbook/data/coordinate-coefficients.json'


def authored(n,*,chapter_part=None,**data):
    entry=build_card(n,**data)
    entry['source']['chapter']='XI'
    if chapter_part:
        entry['id']=f"atanasyan-7-9-main-{n}-part-{'абвгдежзи'.index(chapter_part)+1}"
        entry['source']['subpart']=chapter_part
    if entry['kind']=='exercise':
        entry['help'][1].update(theoryIds=['atanasyan-7-9-theory-93-part-1','atanasyan-7-9-theory-91-part-1'],
                                text='Проверь направление, затем сравни модули двух исходных стрелок.')
    entry['review']['reviewer']='Атанасян 7–9, издание 2023 года, с. 246–251. Связь коэффициента с направлением и длиной, перевод единиц и доли диагонали проверены по рисунку и независимым вычислениям.'
    return entry


def foundations():
    f=figure(dict(O=(0,0),A=(2,0),B=(1,2),K=(4,0),P=(7,6)),'OA OB OK KP OP')
    pair=f('Две независимые стрелки','OA OB')
    span=f('Две копии a и три копии b','OK KP OP')
    col=figure(dict(O=(0,0),A=(2,0),B=(1,2),P=(-2,-4)),'OA OB')('Частный случай: коэффициент при a равен нулю','OA OB OP')
    q93=authored(93,title='Разложение по двум неколлинеарным векторам',pages=[246,247,248],
        question='В каком случае всякий вектор плоскости p можно единственным способом представить в виде xa+yb? Объясни построение и существование обоих коэффициентов.',
        answer='Необходимы два неколлинеарных вектора a и b. Из O отложи p, через его конец проведи прямую вдоль b до пересечения с прямой a. Первый участок пути кратен a, второй — b. Если бы пары коэффициентов различались, после вычитания получилась бы ненулевая кратная a, равная кратной b, вопреки неколлинеарности.',
        hint='Рассмотри две отдельные задачи. Сначала найди подходящие пути вдоль a и b, затем исключи две разные пары коэффициентов.',
        steps=[('Узнай, когда стрелка имеет вид ka','Если a≠0, любой коллинеарный ей p равен ka. Для сонаправленных ненулевых k=|p|/|a|, для противоположных k=−|p|/|a|. Когда p=0, берут k=0.','Чтобы разделить на |a|, исходный вектор должен быть ненулевым.'),
               ('Построй существующее разложение','Для произвольного p=O→P отметь K как пересечение прямой a с прямой через P, параллельной b. Тогда O→K=xa, K→P=yb, а их сумма даёт p. Для p, коллинеарного b, можно взять x=0. На модели первая стрелка равна 2a, вторая 3b.','У неколлинеарных направлений пересечение единственно; нулевые множители разрешены.'),
               ('Обоснуй единственность','Вычти x₁a+y₁b из xa+yb. Из 0=(x−x₁)a+(y−y₁)b следует x=x₁, иначе a выражался бы через b. Затем (y−y₁)b=0 и b≠0 дают y=y₁. В строке доказательства на с. 248 коэффициент второго участка должен быть y: именно он умножает b.','Два неколлинеарных вектора образуют базис плоскости.')],
        frames=[pair,pair,span,col],cases=[pair,span,col],prompts=[('На модели a=(2;0), b=(1;2), p=(7;6). Найди y по вертикали.', '3','Вертикальное смещение приходит только от b: 2y=6.'),
        ('В другом примере a=(1;0), b=(2;1), p=(1;−2). Найди x.', '5','По вертикали y=−2. По горизонтали x−4=1.')])
    f=figure(dict(O=(0,0),I=(1,0),J=(0,1),H=(3,0),P=(3,-2),Q=(2,1)),'OI OJ OH HP OQ')
    axes=f('Два единичных направления','OI OJ');components=f('Три вправо, два вниз','OH HP OP')
    add=figure(dict(O=(0,0),A=(3,-2),B=(5,-1),H=(5,0)),'OA AB OB')('Покомпонентная сумма','OA AB OB')
    q94=authored(94,title='Координаты вектора и действия с ними',pages=[248,249,250],
        question='Что означают координаты вектора в прямоугольной системе? Как по ним находят координаты суммы, разности и произведения на число?',
        answer='Единичные i и j направлены по положительным осям. Если p=xi+yj, то координаты p равны (x;y). Сумма и разность складывают или вычитают соответствующие координаты. У kp обе координаты умножаются на k. Эти правила следуют из единственности разложения и распределительных законов.',
        hint='Сначала прочитай горизонтальный шаг, затем вертикальный. Знак говорит, в какую из двух сторон направлен каждый шаг.',
        steps=[('Задай координатный базис','Отмечаем общий ноль O, взаимно перпендикулярные оси и одинаковую единицу длины. Векторы i,j имеют длину 1. У нулевого вектора обе координаты нулевые.','Координаты — коэффициенты разложения по выбранным базисным векторам.'),
               ('Собери вектор по паре','Для (3;−2) возьми 3i и −2j, затем сложи. Получится смещение вправо на 3 и вниз на 2. У равных векторов обе координаты совпадают и обратно.','Коэффициенты разложения по неколлинеарной паре единственны.'),
               ('Действуй отдельно по осям','Для a=(x₁;y₁), b=(x₂;y₂) имеем a+b=(x₁+x₂;y₁+y₂), a−b=(x₁−x₂;y₁−y₂), ka=(kx₁;ky₁). Например, (3;−2)+(2;1)=(5;−1).','В распределительном законе слагаемые при i группируются только с i, при j только с j.')],
        frames=[axes,axes,components,add],cases=[axes,components,add],
        prompts=[('Какова ордината вектора 3i−2j?', '-2','Читай коэффициент при j вместе со знаком.'),
                 ('В новом примере a=(−1;4), b=(2;−3). Какова горизонтальная составляющая 2a−b?', '-4','Вычисли 2×(−1)−2.')])
    return [q93,q94]


def graded(entry,formats,feedback):
    canonical=formats[0]
    if canonical in {'1/2','-1/2','-1/4'}:
        formats.append({'1/2':'½','-1/2':'-½','-1/4':'-¼'}[canonical])
    if not canonical.startswith('-'):
        formats.extend('+'+item for item in list(formats))
    entry['answer']={'mode':'exact','prompt':'Введи k в виде целого числа или несократимой дроби через черту.','accepted':formats,'feedback':feedback}
    return entry


def lengths():
    rows=[
        ('а','противоположно направлены','0,5 см','2 см','Обе длины уже выражены в сантиметрах. Раздели 2 на 0,5: в одной длинной стрелке четыре короткие.',-4,['-4','-4,0','-4.0'],'Для противоположных векторов коэффициент отрицательный.','Если при том же отношении длин направления совпадут, каким станет k?', '4','Сохрани модуль и измени знак.','В новом случае m и n противоположны, их длины 2 и 6 см. Найди k.', '-3','Длина результата утроилась, а его направление противоположно.'),
        ('б','сонаправлены','12 см','24 дм','В одном дециметре 10 сантиметров. Поэтому |n|=240 см, и |n|/|m|=240/12=20.',20,['20','20,0','20.0'],'Переведи 24 дм в сантиметры прежде, чем делить на 12 см.','Скольким сантиметрам равны исходные 24 дм?', '240','Умножь 24 на 10.','У другой сонаправленной пары длины 30 см и 9 дм. Найди k.', '3','9 дм=90 см, затем 90/30=3.'),
        ('в','противоположно направлены','400 мм','4 дм','Один дециметр равен 100 мм, значит 4 дм=400 мм. Длины равны, а направления противоположны.',-1,['-1','-1,0','-1.0'],'Длины после перевода равны, но противоположные направления требуют минуса.','Скольким миллиметрам равны 4 дм?', '400','Умножь 4 на 100.','В другом примере |m|=500 мм, |n|=1 дм, направления противоположны. Найди k.', '-0,2','1 дм=100 мм. Величина k равна 100/500, со знаком минус.'),
        ('г','сонаправлены','√2 см','√50 см','√50=√(25·2)=5√2. Отношение (5√2)/√2 равно 5.',5,['5','5,0','5.0'],'Отношение длин берётся до возведения в квадрат; √25=5.','Во сколько раз квадрат длины n больше квадрата длины m?', '25','Сравни 50 и 2.','У другой сонаправленной пары длины √3 и √48. Найди k.', '4','Разложи 48 на 16·3 и извлеки корень.')]
    result=[]
    for part,direction,m,n,conversion,k,accepted,feedback,p1,a1,h1,p2,a2,h2 in rows:
        f=figure(dict(O=(0,0),A=(1,0),B=(0,2),C=(k,2)))
        first=figure(dict(O=(0,0),A=(1,0)))('Один шаг исходного масштаба крупно','OA')
        same=f('Две стрелки в масштабе |m|','OA BC')
        example=figure(dict(P=(0,0),Q=(1,0),R=(0,2),S=(-k,2)))('Для сравнения: разворот второй','PQ RS')
        sign='отрицательный' if k<0 else 'положительный'
        e=authored(998,chapter_part=part,pages=[251],question=f'Дано n=km. Векторы m и n {direction}, |m|={m}, |n|={n}. Найди k.',
            answer=f'{conversion} При указанных направлениях k {sign}, поэтому k={k}.',
            hint='Определи знак по направлениям. Затем раздели длину результата n на длину исходного m в одинаковых единицах.',
            steps=[('Выбери знак множителя',f'В условии стрелки {direction}. Значит, искомый коэффициент {sign}. Точное число зависит от отношения длин.', 'Знак и отношение длин — две отдельные части решения.'),
                   ('Сравни длины',conversion,'Делят модуль полученного вектора на модуль исходного; единицы сокращаются.'),
                   ('Проверь равенство',f'В модели длина m принята за единицу. Вторая стрелка имеет подписанное смещение {k} таких единиц. Умножение m на {k} воспроизводит и длину, и направление n.', 'Переключи схему на разворот: модули останутся теми же, знак коэффициента изменится.')],
            frames=[same,first,same,example],cases=[first,same,example],prompts=[(p1,a1,h1),(p2,a2,h2)])
        result.append(graded(e,accepted,feedback))
    return result


def diagonal():
    points=dict(A=(0,0),B=(2,4),C=(8,4),D=(6,0),O=(4,2),M=(2,1))
    f=figure(points,'AB BC CD DA AC BD')
    # The left arrow is the result, the right arrow is the original multiplied by k.
    rows=[
        ('а','AC','AO',Fraction(2),'O — середина AC, значит AO составляет половину AC. Стрелки A→C и A→O начинаются в A и идут в одну сторону.','Делить пополам нужно AC, чтобы получить AO. Здесь ищут обратный переход: от AO к AC.','Пусть AC=12. Найди AO.', '6','Середина делит диагональ пополам.','В другой фигуре A→C=3A→N. Найди k в A→N=kA→C.', '1/3','Укоротить втрое — умножить на одну треть.'),
        ('б','BO','BD',Fraction(1,2),'O лежит посередине BD. От B до O проходим первую половину пути B→D.','Обе стрелки идут из B в сторону D, но BO короче BD вдвое.','При BD=14 найди BO.', '7','Длина половины диагонали — половина 14.','На другом рисунке N лежит в четверти пути из B в D. Какой k в B→N=kB→D?', '1/4','Четверть от начала означает движение по направлению B→D.'),
        ('в','OC','CA',Fraction(-1,2),'O→C — половина диагонали, направленная к C. Стрелка C→A идёт по той же прямой в обратную сторону.','Сравни начало и конец обеих стрелок: k должен быть отрицательным.','Если CA=18, чему равен модуль O→C?', '9','O — середина диагонали.','В другом случае N→C составляет треть CA по длине и направлена против C→A. Укажи k.', '-1/3','Половину замени третью; противоположность даёт минус.'),
        ('г','AB','DC',Fraction(1),'У параллелограмма A→B и D→C — пара равных и сонаправленных противоположных сторон.','Не путай стрелку D→C со стрелкой C→D.','Если AB=9, чему равна длина DC?', '9','Противоположные стороны параллелограмма равны.','При замене D→C на C→D в правой части каким станет коэффициент?', '-1','Разворот равной стрелки меняет знак.'),
        ('д','BC','DA',Fraction(-1),'B→C сонаправлена с A→D. Стрелка D→A, указанная справа, развёрнута, а длина не изменилась.','При равных длинах остаётся выбрать +1 или −1 по направлению.','Если длина DA равна 8, найди длину BC.', '8','У противоположных сторон длины совпадают.','Если в левой части заменить B→C на C→B, каким станет коэффициент при D→A?', '1','Теперь обе стрелки направлены в одну сторону.'),
        ('е','AM','CA',Fraction(-1,4),'M — середина AO, а O — середина AC. Следовательно AM=AC/4. A→M направлен против C→A.','Две последовательные середины дают четверть, а обратное направление — минус.','При AC=20 чему равна длина AM?', '5','Раздели 20 пополам дважды.','В новой фигуре N лежит на одной пятой пути от A к C. Найди k в A→N=kC→A.', '-1/5','Берём пятую часть в противоположном направлении.'),
        ('ж','MC','AM',Fraction(3),'На диагонали порядок точек A,M,O,C. Длина AM одна четверть AC, а MC три четверти; оба движения идут к C.','MC здесь сравнивается с AM, а не со всей диагональю.','Если AM=4, найди длину MC.', '12','В оставшемся участке помещаются три длины AM.','В новом примере AN=AC/5. Найди k в N→C=kA→N.', '4','Из пяти равных долей после N остаются четыре.'),
        ('з','AC','CM',Fraction(-4,3),'CM занимает три четверти всей диагонали. A→C направлен к C, тогда как C→M идёт к A. Поэтому отношение длин 4:3 и знак отрицательный.','Размер правой стрелки равен ¾ от левой. Делим целое на ¾, а не умножаем на ¾.','Пусть AC=16. Назови длину CM.', '12','Между C и M лежат три из четырёх одинаковых долей.','Если AN=AC/5, найди k в A→C=kC→N.', '-5/4','Остаток NC равен 4/5 целой диагонали; обрати отношение и проверь знак.')]
    cards=[]
    for part,left,right,value,why,hint,p1,a1,h1,p2,a2,h2 in rows:
        k=str(value)
        same=value>0
        align='совпадают' if same else 'противоположны'
        allv=f('Укажи оба рассматриваемых вектора',right+' '+left)
        start=f('Прочти правую стрелку',right)
        finish=f('Прочти левую стрелку',left)
        e=authored(999,chapter_part=part,pages=[251],question=f'У параллелограмма ABCD диагонали пересекаются в O, M — середина AO. Найди k, если {left[0]}→{left[1]}=k·{right[0]}→{right[1]}, либо объясни невозможность.',
            answer=f'{why} Получается k={k}.',hint=hint,
            steps=[('Найди правую стрелку',f'Именно {right[0]}→{right[1]} умножают на k. На первом рисунке проследи от {right[0]} к {right[1]}, затем укажи левую стрелку {left[0]}→{left[1]}.','Коэффициент относится к вектору в правой части.'),
                   ('Используй свойство диагоналей или сторон',why,'Середины сравнивают с соответствующими целыми отрезками. У противоположных сторон учитывают порядок букв.'),
                   ('Проверь размер и знак',f'Направления {align}. Модуль k равен длине {left}, делённой на длину {right}, поэтому k={k}. Умножение правой стрелки на это число даёт левую.','Скалярный множитель определён однозначно, потому что правая стрелка ненулевая.')],
            frames=[allv,start,finish,allv],cases=[start,finish,allv],prompts=[(p1,a1,h1),(p2,a2,h2)])
        forms=[k]
        if value.denominator==1:forms.extend([k+',0',k+'.0'])
        elif value.denominator in (2,4):
            decimal=str(float(value));forms.extend([decimal,decimal.replace('.',',')])
        cards.append(graded(e,forms,hint))
    a=f('Первая диагональ','AO');b=f('Вторая диагональ','BD');both=f('Разные направления','AO BD')
    impossible=authored(999,chapter_part='и',pages=[251],
        question='В том же невырожденном параллелограмме ABCD, O — точка пересечения диагоналей, M — середина AO. Можно ли подобрать k в равенстве A→O=k·B→D?',
        answer='Нельзя. A→O ненулевой и направлен вдоль AC; B→D лежит на другой диагонали. Эти пересекающиеся прямые различны, поэтому векторы не коллинеарны. Множитель k=0 тоже не подходит, поскольку A и O различны.',
        hint='Прежде чем сравнивать длины, проверь, может ли умножение повернуть одну диагональ к другой.',
        steps=[('Определи несущие прямые','A→O лежит на AC. Вторая стрелка лежит на BD. Эти диагонали пересекаются внутри невырожденного параллелограмма и не лежат на одной прямой.','У параллелограмма ненулевой площади смежные стороны неколлинеарны.'),
               ('Проверь все множители','При k≠0 вектор kB→D остаётся вдоль BD. При k=0 получился бы нуль, но A→O ненулевой. Так исключены все вещественные k.','Одного сходства длин для равенства векторов недостаточно.'),
               ('Найди контрольный признак','На модели A→O=(4;2), B→D=(4;−4). По горизонтали k пришлось бы взять 1, а по вертикали −1/2. Разные значения подтверждают геометрический вывод.','Для равенства обеих составляющих требуется одно и то же число.')],
        frames=[both,a,b,both],cases=[a,b,both],prompts=[('На модели по горизонталям получилось 4=4k. Какое k требует одна эта координата?', '1','Раздели 4 на 4.'),('Для другой пары (2;6)=k(4;3) какое k диктуют только вертикали?', '2','Вычисли 6/3. Затем сравни с горизонтальным отношением 2/4.')])
    impossible['answer']={'mode':'manual','prompt':'Объясни, почему одно число подходит или не подходит сразу по направлению и по длине.'}
    return cards+[impossible]


def build():
    return {'bookId':BOOK,'lessons':foundations()+lengths()+diagonal()}


if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    args=parser.parse_args()
    text=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if args.check:
        assert OUT.read_text()==text
    else:
        OUT.write_text(text)
